// idpSignOutLabel names the identity provider's sign-out like the sign-in button names its sign-in:
// "Sign out of Authentik", or "Sign out of SSO" when the provider has no name of its own.
func idpSignOutLabel(name string) string {
	if name == "" || name == "Single sign-on" {
		return "Sign out of SSO"
	}
	return "Sign out of " + name
}

